#!/usr/bin/env bash
set -euo pipefail
PANEL_DIR="${PTERODACTYL_DIRECTORY:-/var/www/pterodactyl}"
panel_status(){ [[ -f "$PANEL_DIR/artisan" ]]&&echo '● DETECTED'||echo '○ NOT INSTALLED'; }
install_panel(){ require_root; ui_section 'PTERODACTYL PANEL'; read -r -p '  Panel domain/FQDN › ' PANEL_FQDN; [[ -n $PANEL_FQDN ]]|| { ui_error 'Domain required.';return; }; apt_install curl ca-certificates git unzip tar nginx mariadb-server redis-server; apt_install php8.3 php8.3-cli php8.3-gd php8.3-mysql php8.3-mbstring php8.3-bcmath php8.3-xml php8.3-curl php8.3-zip php8.3-fpm composer; mkdir -p "$PANEL_DIR"; cd "$PANEL_DIR"; curl -fL -o panel.tar.gz https://github.com/pterodactyl/panel/releases/latest/download/panel.tar.gz; tar -xzf panel.tar.gz; rm -f panel.tar.gz; chmod -R 755 storage bootstrap/cache; cp .env.example .env; COMPOSER_ALLOW_SUPERUSER=1 composer install --no-dev --optimize-autoloader; php artisan key:generate --force; chown -R www-data:www-data "$PANEL_DIR"; ui_success 'Panel application files installed.'; ui_warning 'Database, mail, queue, Nginx/TLS and first-admin setup must be completed with the version-matched official Pterodactyl procedure.'; }
panel_maintenance(){ require_root; [[ -f "$PANEL_DIR/artisan" ]]|| { ui_error 'Panel not found.';return; }; cd "$PANEL_DIR"; php artisan optimize:clear; php artisan migrate --force; chown -R www-data:www-data storage bootstrap/cache; ui_success 'Maintenance completed.'; }
